function normalizeImage(value){return typeof value==='string'?{dataUrl:value}:value||{};}
function matchImage(name,products){const base=String(name).split(/[\\/]/).at(-1).replace(/\.(?:png|jpe?g|webp|gif)$/i,'');const ordered=products.slice().sort((a,b)=>b.sku.length-a.sku.length);for(const p of ordered){if(base.toLowerCase()===p.sku.toLowerCase())return {productId:p.id,order:1};const prefix=base.slice(0,p.sku.length);const rest=base.slice(p.sku.length);if(prefix.toLowerCase()===p.sku.toLowerCase()&&/^[+_-]\d+$/.test(rest))return {productId:p.id,order:Number(rest.slice(1))||1};}return {productId:'',order:1};}
